      sources:[organization('pratico-van-pelt-2019',['ch. 17, “Waw Consecutive”'], 'Familiar classroom location and searchable terminology'), content('gesenius-1910',['§49b–c; printed pp. 133–134'], 'Directly printed consecutive-imperfect description and examples','partial'), appGuidance('Sequential-form distinction and anti-reversal caution')]
